mapper.sql:
WHERE 1 = 1

    AND t.status = #{query.status}


    AND t.task_type = #{query.taskType}


    AND c.case_no = #{query.caseNo}


    AND (
        t.task_no LIKE CONCAT('%', #{query.keyword}, '%')
        OR c.case_no LIKE CONCAT('%', #{query.keyword}, '%')
    )

mapper.select:
SELECT COUNT(*)
FROM analysis_task
WHERE image_file_id = #{imageFileId}
  AND task_type = #{taskType}
  AND status IN ('CREATED', 'WAITING', 'RUNNING', 'RETRYING')
